// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetHealth Status des Servers
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// ListMovements Buchungen, neueste zuerst
	// (GET /movements)
	ListMovements(ctx context.Context, request ListMovementsRequestObject) (ListMovementsResponseObject, error)
	// CreateMovement Buchung anlegen
	// (POST /movements)
	CreateMovement(ctx context.Context, request CreateMovementRequestObject) (CreateMovementResponseObject, error)
	// ReverseMovement Buchung stornieren
	// (POST /movements/{id}/reversal)
	ReverseMovement(ctx context.Context, request ReverseMovementRequestObject) (ReverseMovementResponseObject, error)
	// ListProducts Alle Produkte, sortiert nach Name
	// (GET /products)
	ListProducts(ctx context.Context, request ListProductsRequestObject) (ListProductsResponseObject, error)
	// CreateProduct Produkt manuell anlegen
	// (POST /products)
	CreateProduct(ctx context.Context, request CreateProductRequestObject) (CreateProductResponseObject, error)
	// DeleteProduct Produkt mit Barcodes, Buchungen und Bild löschen
	// (DELETE /products/{id})
	DeleteProduct(ctx context.Context, request DeleteProductRequestObject) (DeleteProductResponseObject, error)
	// GetProduct Ein Produkt
	// (GET /products/{id})
	GetProduct(ctx context.Context, request GetProductRequestObject) (GetProductResponseObject, error)
	// UpdateProduct Produkt ändern (JSON Merge Patch)
	// (PATCH /products/{id})
	UpdateProduct(ctx context.Context, request UpdateProductRequestObject) (UpdateProductResponseObject, error)
	// AddBarcode Barcode einem Produkt zuordnen
	// (POST /products/{id}/barcodes)
	AddBarcode(ctx context.Context, request AddBarcodeRequestObject) (AddBarcodeResponseObject, error)
	// RemoveBarcode Barcode von einem Produkt entfernen
	// (DELETE /products/{id}/barcodes/{code})
	RemoveBarcode(ctx context.Context, request RemoveBarcodeRequestObject) (RemoveBarcodeResponseObject, error)
	// DeleteProductImage Produktbild und Bildquelle entfernen
	// (DELETE /products/{id}/image)
	DeleteProductImage(ctx context.Context, request DeleteProductImageRequestObject) (DeleteProductImageResponseObject, error)
	// GetProductImage Produktbild
	// (GET /products/{id}/image)
	GetProductImage(ctx context.Context, request GetProductImageRequestObject) (GetProductImageResponseObject, error)
	// UploadProductImage Eigenes Foto als Produktbild hochladen
	// (PUT /products/{id}/image)
	UploadProductImage(ctx context.Context, request UploadProductImageRequestObject) (UploadProductImageResponseObject, error)
	// MergeProduct Produkt in ein anderes Produkt überführen
	// (POST /products/{id}/merge)
	MergeProduct(ctx context.Context, request MergeProductRequestObject) (MergeProductResponseObject, error)
	// GetShoppingList Einkaufsliste, sortiert nach Name
	// (GET /shopping-list)
	GetShoppingList(ctx context.Context, request GetShoppingListRequestObject) (GetShoppingListResponseObject, error)
	// MarkShoppingItem Produkt für den Einkauf vormerken
	// (POST /shopping-list/items)
	MarkShoppingItem(ctx context.Context, request MarkShoppingItemRequestObject) (MarkShoppingItemResponseObject, error)
	// UnmarkShoppingItem Vormerkung entfernen
	// (DELETE /shopping-list/items/{product_id})
	UnmarkShoppingItem(ctx context.Context, request UnmarkShoppingItemRequestObject) (UnmarkShoppingItemResponseObject, error)
	// SendShoppingSnapshot Einkaufsliste per MQTT neu senden
	// (POST /shopping-list/snapshot)
	SendShoppingSnapshot(ctx context.Context, request SendShoppingSnapshotRequestObject) (SendShoppingSnapshotResponseObject, error)
	// GetSummary Zusammenfassung des Vorrats
	// (GET /summary)
	GetSummary(ctx context.Context, request GetSummaryRequestObject) (GetSummaryResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

